class Solution:
    def minOperations(self, nums: List[int], x: int) -> int:
        target = sum(nums) - x               # the untouched middle must sum to this
        if target < 0:
            return -1
        best = -1                            # longest middle subarray with sum == target
        left = window = 0
        for right, v in enumerate(nums):
            window += v
            while window > target:           # all values positive: shrink from the left
                window -= nums[left]
                left += 1
            if window == target:
                best = max(best, right - left + 1)
        return len(nums) - best if best != -1 else -1
